def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n+1")
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        coeff_part = ''
        if abs_coeff != 1 or degree == 0:
            coeff_part = str(abs_coeff)
        var_part = ''
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: encoded and original must be of same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Ensure mapping covers all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    from collections import deque

    # Map each digit to the list of digits it can transform into
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))

    start_str = str(n)
    visited_ints = {int(start_str)}
    queue = deque([start_str])

    while queue:
        current = queue.popleft()
        for idx, ch in enumerate(current):
            if ch in rule_map:
                for new_digit in rule_map[ch]:
                    new_str = current[:idx] + new_digit + current[idx + 1 :]
                    new_int = int(new_str)
                    if new_int not in visited_ints:
                        visited_ints.add(new_int)
                        queue.append(new_str)

    return len(visited_ints)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement is about a day of the week
    def is_day_statement(stmt: str) -> bool:
        words = {w.strip(".,!?;:").upper() for w in stmt.split()}
        return any(day.upper() in words for day in days_of_week)

    # Helper to extract subject and guilt claim from a statement
    def parse_statement(stmt: str, speaker: str):
        # Normalize
        stmt_lower = stmt.lower()
        # Skip if not about guilt
        if "guilty" not in stmt_lower:
            return None, None
        # Determine if statement says "not guilty"
        not_guilty = "not guilty" in stmt_lower
        # Determine subject
        if "i" in stmt_lower.split():
            subject = speaker
        else:
            # Find any uppercase word that matches a known name
            import re
            matches = re.findall(r'\b([A-Z]+)\b', stmt)
            subject = None
            for m in matches:
                if m in statements or m == scenario:
                    subject = m
                    break
        if subject is None:
            return None, None
        return subject, not_guilty

    for speaker, stmts in statements.items():
        for stmt in stmts:
            # Ignore day-of-week statements
            if is_day_statement(stmt):
                continue
            subject, not_guilty = parse_statement(stmt, speaker)
            if subject is None:
                continue  # statement not about guilt or unparsable
            # Determine truth of the statement
            subject_is_guilty = (subject == scenario)
            # If statement says "not guilty", then truth is subject_is_guilty == False
            truth = (not_guilty == (not subject_is_guilty))
            # Check liar status
            is_liar = speaker in liar_count
            if is_liar:
                if truth:
                    return False  # liar told a true statement
            else:
                if not truth:
                    return False  # truth teller told a false statement
    return True

